function test_type_mapping_void(): Bool =
  get_type_mapping("Void") == "void"

function test_type_mapping_array(): Bool =
  get_type_mapping("Array[Int]") == "Array(i32)"

function test_type_mapping_dict(): Bool =
  get_type_mapping("Dictionary[String, Int]") == "Map(String, String)"

function test_type_mapping_extended_array(): Bool =
  get_type_mapping_extended("Array[Float]") == "[]f64"

function test_type_mapping_extended_option(): Bool =
